int lis(vector<int>& a) {
    vector<int> tails;   // tails[k]: smallest end of a run of length k+1
    for (int x : a) {
        auto it = lower_bound(tails.begin(), tails.end(), x);
        if (it == tails.end()) tails.push_back(x);   // run gets longer
        else *it = x;                                // smaller end is better
    }
    return tails.size();
}

